"""Generate report tables from saved scores; never manually transcribe model numbers."""
import json
from pathlib import Path
import sys

ROOT=Path(__file__).resolve().parents[1]
sys.path.insert(0,str(ROOT))
from contextual.training import metrics
from contextual.data import read_jsonl
from contextual.evaluation import file_hash, validate_splits


def main():
    data=ROOT/'data/processed/english_cga_v1.jsonl'
    splits=validate_splits(read_jsonl(data))
    lines=['# Verified results generated from saved predictions','',
           'Generated by `python scripts/generate_verified_summary.py`. Do not edit numeric tables manually.',
           '','All English rows below use the identical English held-out population. F1 is positive-class F1; AP is average precision.',
           '',f'English dataset SHA-256: `{file_hash(data)}`','',
           '| Split | Examples | Positive targets |','|---|---:|---:|']
    for split,rows in splits.items(): lines.append(f'| {split} | {len(rows)} | {sum(r["label"] for r in rows)} |')
    lines+=['','| Model | Threshold | English F1 | English AP | Contextual F1 | Precision | Recall |',
            '|---|---:|---:|---:|---:|---:|---:|']
    for name in ['english_cga_v1_tfidf','english_cga_v1_target_only','english_cga_v1_frozen','english_cga_v1_lora',
                 'english_cga_v1_ensemble','clean_tfidf','contextual_clean_lora_evaluation','clean_ensemble']:
        path=ROOT/'reports'/(name+'.json')
        report=json.loads(path.read_text(encoding='utf-8'))
        records=json.loads(path.with_suffix('.predictions.json').read_text(encoding='utf-8'))
        lookup={r['id']:r for r in records}
        expected=splits['test']
        if any(e['id'] not in lookup or lookup[e['id']]['label']!=e['label'] for e in expected):
            raise ValueError('Report population mismatch: '+name)
        selected=[lookup[e['id']] for e in expected]
        m=metrics([e['label'] for e in selected],[e['score'] for e in selected],report['threshold'])
        contextual=[lookup[e['id']] for e in expected if len(e['texts'])>1]
        c=metrics([e['label'] for e in contextual],[e['score'] for e in contextual],report['threshold'])
        lines.append(f"| {name} | {report['threshold']:.10f} | {m['f1']:.6f} | {m['average_precision']:.6f} | {c['f1']:.6f} | {m['precision']:.6f} | {m['recall']:.6f} |")
    for stem in ['english_cga_v1_budget_val','english_cga_v1_budget_test','english_shared_telugu_ensemble_challenge',
                 'english_shared_telugu_lora_challenge','english_cga_v1_telugu_transfer_challenge']:
        report=json.loads((ROOT/'reports'/(stem+'.json')).read_text(encoding='utf-8'))
        records=json.loads((ROOT/'reports'/(stem+'.predictions.json')).read_text(encoding='utf-8'))
        lines+=['','## '+stem,'','| Parents retained (maximum) | n | F1 | AP |','|---:|---:|---:|---:|']
        for budget in report['budgets']:
            m=metrics([r['label'] for r in records],[r['scores_by_parent_budget'][budget] for r in records],report['threshold'])
            lines.append(f"| {budget} | {m['n']} | {m['f1']:.6f} | {m['average_precision']:.6f} |")
    lines+=['','These budget tables use the full named evaluation population. See `ENGLISH_POST_RUN_REVIEW.md` for contextual-only tables, uncertainty and limitations.',
            '','The Telugu challenge has only 51 authored targets. These are diagnostics, not independent language-wide benchmark results.']
    output=ROOT/'VERIFIED_RESULTS.md'
    output.write_text('\n'.join(lines)+'\n',encoding='utf-8')
    print(output)


if __name__=='__main__': main()
